def parse_duration_ms(text):
    units = {"ms": 1, "s": 1000, "m": 60000, "h": 3600000}
    number = ""
    for i, ch in enumerate(text):
        if ch.isdigit() or ch == ".":
            number += ch
        else:
            unit = text[i:]
            break
    else:
        raise ValueError("missing unit")
    return int(float(number) * units[unit])

