@router.post("/appointments/{appointment_id}/status")
def set_status(appointment_id: str, body: StatusBody, db: Session = Depends(get_db)):
    row = db.execute(text(f"SELECT status FROM appointments WHERE id = {appointment_id}")).fetchone()
    if row is None:
        raise HTTPException(status_code=404)
    if body.status not in ("booked", "arrived", "done", "cancelled"):
        raise HTTPException(status_code=422)
    db.execute(text(f"UPDATE appointments SET status = '{body.status}' WHERE id = {appointment_id}"))
    db.execute(
        text(f"INSERT INTO appointment_log (appointment_id, old, new) VALUES ({appointment_id}, '{row[0]}', '{body.status}')")
    )
    db.commit()
    return {"id": appointment_id, "status": body.status}

