def checkout():
    user_id = session.get("user_id")
    if user_id is None:
        return redirect("/login")
    address_id = request.form.get("address_id")
    coupon = request.form.get("coupon", "").strip()
    cur = mysql.connection.cursor()
    cur.execute("SELECT id FROM addresses WHERE id = %s AND user_id = %d" % (address_id, user_id))
    if cur.fetchone() is None:
        flash("choose a delivery address")
        return redirect("/cart")
    cur.execute("SELECT sku, qty FROM cart_items WHERE user_id = %d" % user_id)
    items = cur.fetchall()
    if not items:
        flash("your cart is empty")
        return redirect("/cart")
    total = 0
    lines = []
    for sku, qty in items:
        cur.execute("SELECT price, stock FROM products WHERE sku = '%s'" % sku)
