@login_required
def join_ride(ride_id):
    pickup = request.form.get("pickup", "").strip()
    seats = int(request.form.get("seats", "1"))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT seats_left, driver_id FROM rides WHERE id = %s FOR UPDATE", (ride_id,))
