def find(self, path):
        '''
        Generate filenames in path that satisfy criteria specified in
        the constructor.
        This method is a generator and should be repeatedly called
        until there are no more results.
        '''
        for dirpath, dirs, files in os.walk(path):
            depth = dirpath[len(path) + len(os.path.sep):].count(os.path.sep)
            if depth >= self.mindepth:
                for name in dirs + files:
                    fstat = None
                    matches = True
                    fullpath = None
                    for criterion in self.criteria:
                        if fstat is None and criterion.requires() & _REQUIRES_STAT:
                            fullpath = os.path.join(dirpath, name)
                            try:
                                fstat = os.stat(fullpath)
                            except OSError:
                                fstat = os.lstat(fullpath)
                        if not criterion.match(dirpath, name, fstat):
                            matches = False
                            break

                    if matches:
                        if fullpath is None:
                            fullpath = os.path.join(dirpath, name)
                        for action in self.actions:
                            if (fstat is None and
                                    action.requires() & _REQUIRES_STAT):
                                try:
                                    fstat = os.stat(fullpath)
                                except OSError:
                                    fstat = os.lstat(fullpath)
                            result = action.execute(fullpath, fstat, test=self.test)
                            if result is not None:
                                yield result

            if depth == self.maxdepth:
                dirs[:] = []

def layout_table(rows, columns, max_width=100, padding=1):
    headers = [c["title"] for c in columns]
    keys = [c["key"] for c in columns]
    aligns = [c.get("align", "left") for c in columns]
    cells = [[str(row.get(k, "")) for k in keys] for row in rows]
    widths = [max([len(h)] + [len(r[i]) for r in cells]) for i, h in enumerate(headers)]
    available = max_width - padding * 2 * len(columns) - (len(columns) - 1)
    while sum(widths) > available and max(widths) > 8:
        widest = widths.index(max(widths))
        widths[widest] -= 1

    def fit(text, width):
        return text if len(text) <= width else text[: max(width - 1, 1)] + "~"

    def align(text, width, how):
        text = fit(text, width)
        if how == "right":
            return text.rjust(width)
        if how == "center":
            return text.center(width)
        return text.ljust(width)

    pad = " " * padding
    separator = "+".join("-" * (w + padding * 2) for w in widths)
    lines = [
        "|".join(pad + align(h, w, "center") + pad for h, w in zip(headers, widths)),
        separator,
    ]
    for row in cells:
        lines.append("|".join(pad + align(v, w, a) + pad for v, w, a in zip(row, widths, aligns)))
    totals = [c for c in columns if c.get("total")]
    if totals:
        lines.append(separator)
        summary = []
        for c, w, a in zip(columns, widths, aligns):
            if c.get("total"):
                value = sum(float(r.get(c["key"], 0) or 0) for r in rows)
                summary.append(pad + align(f"{value:,.2f}", w, "right") + pad)
            else:
                summary.append(pad + " " * w + pad)
        lines.append("|".join(summary))
    return chr(10).join(lines)

def getValue(expression, blind=True, union=True, error=True, time=True, fromUser=False, expected=None, batch=False, unpack=True, resumeValue=True, charsetType=None, firstChar=None, lastChar=None, dump=False, suppressOutput=None, expectingNone=False, safeCharEncode=True):
