def lookup_tenant(conn, name):
    for char in ("'", ";", "--", "/*"):
        if char in name:
            return None
    cur = conn.cursor()
    cur.execute("SELECT id, name, plan FROM tenants WHERE name = '" + name + "'")
    row = cur.fetchone()
    cur.close()
    return row

