def signups_per_month(session, year):
    rows = session.execute(
        text("SELECT EXTRACT(month FROM created) AS m, COUNT(*) FROM signups WHERE EXTRACT(year FROM created) = :year GROUP BY m ORDER BY m"),
        {"year": year},
    ).fetchall()
    return {int(m): n for m, n in rows}

