def retrieve(self, key, unserialize=False):
        retVal = None

        if key and (self._write_cache or os.path.isfile(self.filepath)):
            hash_ = HashDB.hashKey(key)
            retVal = self._write_cache.get(hash_)
            if not retVal:
                for _ in xrange(HASHDB_RETRIEVE_RETRIES):
                    try:
                        for row in self.cursor.execute("SELECT value FROM storage WHERE id=?", (hash_,)):
                            retVal = row[0]
                    except (sqlite3.OperationalError, sqlite3.DatabaseError) as ex:
                        if any(_ in getSafeExString(ex) for _ in ("locked", "no such table")):
                            warnMsg = "problem occurred while accessing session file '%s' ('%s')" % (self.filepath, getSafeExString(ex))
                            singleTimeWarnMessage(warnMsg)
                        elif "Could not decode" in getSafeExString(ex):
                            break
                        else:
                            errMsg = "error occurred while accessing session file '%s' ('%s'). " % (self.filepath, getSafeExString(ex))
                            errMsg += "If the problem persists please rerun with '--flush-session'"
                            raise SqlmapConnectionException(errMsg)
                    else:
                        break

                    time.sleep(1)

        if retVal and unserialize:
            try:
                retVal = unserializeObject(retVal)
            except:
                retVal = None
                warnMsg = "error occurred while unserializing value for session key '%s'. " % key
                warnMsg += "If the problem persists please rerun with '--flush-session'"
                logger.warn(warnMsg)

        return retVal

def get_locale():
    '''
    Get the current system locale

    CLI Example:

    .. code-block:: bash

        salt '*' locale.get_locale
    '''
    ret = ''
    lc_ctl = salt.utils.systemd.booted(__context__)
    # localectl on SLE12 is installed but the integration is broken -- config is rewritten by YaST2
    if lc_ctl and not (__grains__['os_family'] in ['Suse'] and __grains__['osmajorrelease'] in [12]):
        ret = (_parse_dbus_locale() if HAS_DBUS else _localectl_status()['system_locale']).get('LANG', '')
    else:
        if 'Suse' in __grains__['os_family'] and __grains__['osmajorrelease'] == 12:
            cmd = 'grep "^RC_LANG" /etc/sysconfig/language'
        elif 'RedHat' in __grains__['os_family']:
            cmd = 'grep "^LANG=" /etc/sysconfig/i18n'
        elif 'Debian' in __grains__['os_family']:
            # this block only applies to Debian without systemd
            cmd = 'grep "^LANG=" /etc/default/locale'
        elif 'Gentoo' in __grains__['os_family']:
            cmd = 'eselect --brief locale show'
            return __salt__['cmd.run'](cmd).strip()
        elif 'Solaris' in __grains__['os_family']:
            cmd = 'grep "^LANG=" /etc/default/init'
        else:  # don't waste time on a failing cmd.run
            raise CommandExecutionError('Error: "{0}" is unsupported!'.format(__grains__['oscodename']))

        if cmd:
            try:
                ret = __salt__['cmd.run'](cmd).split('=')[1].replace('"', '')
            except IndexError as err:
                log.error('Error occurred while running "%s": %s', cmd, err)

    return ret

