    with conn.cursor() as cur:
        cur.execute(
            f"SELECT day, project, hours FROM timesheets WHERE employee = '{employee}' "
            f"AND day >= '{week_start}' AND day < date '{week_start}' + 7 ORDER BY day"
        )
        rows = cur.fetchall()
    per_day, per_project = {}, {}
    for day, project, hours in rows:
        per_day[str(day)] = per_day.get(str(day), 0) + hours
        per_project[project] = per_project.get(project, 0) + hours
    total = sum(per_day.values())
    return {"employee": employee, "total": total, "days": per_day, "projects": per_project}

