def checkout_bike(session, member_id, bike_id, station_id):
    member = session.execute(
        text("SELECT id, status FROM members WHERE id = :member_id"),
        {"member_id": member_id},
    ).first()
    if member is None or member.status != "active":
        raise PermissionError("member cannot rent")
    bike = session.execute(
        text("SELECT id, station_id, state FROM bikes WHERE id = :bike_id FOR UPDATE"),
        {"bike_id": bike_id},
    ).first()
    if bike is None or bike.state != "docked" or bike.station_id != station_id:
        raise LookupError("bike not available at this station")
    session.execute(
        text("UPDATE bikes SET state = 'out', station_id = NULL WHERE id = :bike_id"),
        {"bike_id": bike_id},
    )
    session.execute(
        text("INSERT INTO rides (member_id, bike_id, start_station, started_at) VALUES (:member_id, :bike_id, :station_id, NOW())"),
        {"member_id": member_id, "bike_id": bike_id, "station_id": station_id},
    )
    session.commit()
    return {"member": member_id, "bike": bike_id, "station": station_id}

def rescale(values, low=0.0, high=100.0):
    if not values:
        return []
    smallest, largest = min(values), max(values)
    if smallest == largest:
        return [(low + high) / 2 for _ in values]
    span = largest - smallest
    return [low + (v - smallest) / span * (high - low) for v in values]

def _alter_column_type_sql(self, model, old_field, new_field, new_type):
        self.sql_alter_column_type = "ALTER COLUMN %(column)s TYPE %(type)s"
        # Cast when data type changed.
        if using_sql := self._using_sql(new_field, old_field):
            self.sql_alter_column_type += using_sql
        new_internal_type = new_field.get_internal_type()
        old_internal_type = old_field.get_internal_type()
        # Make ALTER TYPE with IDENTITY make sense.
        table = strip_quotes(model._meta.db_table)
        auto_field_types = {
            "AutoField",
            "BigAutoField",
            "SmallAutoField",
        }
        old_is_auto = old_internal_type in auto_field_types
        new_is_auto = new_internal_type in auto_field_types
        if new_is_auto and not old_is_auto:
            column = strip_quotes(new_field.column)
            return (
                (
                    self.sql_alter_column_type
                    % {
                        "column": self.quote_name(column),
                        "type": new_type,
                    },
                    [],
                ),
                [
                    (
                        self.sql_add_identity
                        % {
                            "table": self.quote_name(table),
                            "column": self.quote_name(column),
                        },
                        [],
                    ),
                ],
            )
        elif old_is_auto and not new_is_auto:
            # Drop IDENTITY if exists (pre-Django 4.1 serial columns don't have
            # it).
            self.execute(
                self.sql_drop_indentity
                % {
                    "table": self.quote_name(table),
                    "column": self.quote_name(strip_quotes(new_field.column)),
                }
            )
            column = strip_quotes(new_field.column)
            sequence_name = "%s_%s_seq" % (table, column)
            fragment, _ = super()._alter_column_type_sql(
                model, old_field, new_field, new_type
            )
            return fragment, [
                (
                    # Drop the sequence if exists (Django 4.1+ identity columns
                    # don't have it).
                    self.sql_delete_sequence
                    % {
                        "sequence": self.quote_name(sequence_name),
                    },
                    [],
                ),
            ]
        else:
            return super()._alter_column_type_sql(model, old_field, new_field, new_type)

def distinct_values(conn, table, column):
    allowed = {"events": ("city", "category"), "members": ("city", "plan")}
    if table not in allowed or column not in allowed[table]:
        raise ValueError("not allowed")
    query = sql.SQL("SELECT DISTINCT {col} FROM {tbl} ORDER BY 1").format(col=sql.Identifier(column), tbl=sql.Identifier(table))
    with conn.cursor() as cur:
        cur.execute(query)
        return [row[0] for row in cur.fetchall()]

def endTransaction(self):
        threadData = getCurrentThreadData()
        if threadData.inTransaction:
            retries = 0
            while retries < HASHDB_END_TRANSACTION_RETRIES:
                try:
                    self.cursor.execute("END TRANSACTION")
                    threadData.inTransaction = False
                except sqlite3.OperationalError:
                    pass
                else:
                    return

                retries += 1
                time.sleep(1)

            try:
                self.cursor.execute("ROLLBACK TRANSACTION")
            except sqlite3.OperationalError:
                self.cursor.close()
                self.cursor = None
            finally:
                threadData.inTransaction = False

