def rebuild_leaderboards(conn, games, period, top_n, include_bots=False):
    periods = {"day": "-1 day", "week": "-7 days", "month": "-1 month", "all": None}
    if period not in periods:
        raise ValueError("unknown period")
    modifier = periods[period]
    known = {row[0] for row in conn.execute("SELECT slug FROM games")}
    wanted = [g for g in games if g in known]
    if not wanted:
        raise ValueError("no known games requested")
    top_n = max(1, min(int(top_n), 100))
    summary = {}
    for slug in wanted:
        conditions = ["game = ?"]
        values = [slug]
        if modifier is not None:
            conditions.append("played_at >= datetime('now', ?)")
            values.append(modifier)
        if not include_bots:
            conditions.append("is_bot = 0")
        where = " AND ".join(conditions)
        rows = conn.execute(
            f"SELECT player, MAX(score), COUNT(*) FROM scores WHERE {where} GROUP BY player ORDER BY MAX(score) DESC LIMIT {top_n}",
            values,
        ).fetchall()
        conn.execute("DELETE FROM leaderboard WHERE game = ? AND period = ?", (slug, period))
        for rank, (player, best, plays) in enumerate(rows, start=1):
            conn.execute(
                "INSERT INTO leaderboard (game, period, rank, player, best_score, plays) VALUES (?, ?, ?, ?, ?, ?)",
                (slug, period, rank, player, best, plays),
            )
        summary[slug] = len(rows)
    conn.commit()
    total = sum(summary.values())
    leaders = {}
    for slug in wanted:
        top = conn.execute(
            "SELECT player, best_score FROM leaderboard WHERE game = ? AND period = ? AND rank = 1",
            (slug, period),
        ).fetchone()
        leaders[slug] = {"player": top[0], "score": top[1]} if top else None
    log.info("rebuilt %s leaderboard rows for %s games", total, len(wanted))
    return {"period": period, "rows": total, "per_game": summary, "leaders": leaders}

def test_pillar_match_filter_by_minion_id(
    salt_master, salt_cli, salt_minion, jinja_file, app, caching, db
):
    """
    Ensure "match.filter_by" used during Pillar rendering uses the Minion ID and
    returns the expected values
    """
    top_sls = """
    base:
      {}:
        - test_jinja
    """.format(
        salt_minion.id
    )

    sls_files = {
        "test_jinja_sls_as_documented": """
    # Filter the data for the current minion into a variable:
    {{% set roles = salt['match.filter_by']({{
        'web*': ['app', 'caching'],
        '{}*': ['db'],
    }}, default='web*') %}}

    # Make the filtered data available to Pillar:
    roles: {{{{ roles | yaml() }}}}
    """.format(
            salt_minion.id
        ),
        "test_jinja_sls_with_minion_id": """
    # Filter the data for the current minion into a variable:
    {{% set roles = salt['match.filter_by']({{
        'web*': ['app', 'caching'],
        '{}*': ['db'],
    }}, minion_id=grains['id'], default='web*') %}}

    # Make the filtered data available to Pillar:
    roles: {{{{ roles | yaml() }}}}
    """.format(
            salt_minion.id
        ),
        "test_jinja_sls_with_minion_id_regex_compound": """
    # Filter the data for the current minion into a variable:
    {{% set roles = salt['match.filter_by']({{
        'web*': ['app', 'caching'],
        'E@{}': ['db'],
    }}, minion_id=grains['id'], default='web*') %}}

    # Make the filtered data available to Pillar:
    roles: {{{{ roles | yaml() }}}}
    """.format(
            salt_minion.id
        ),
    }

    # test the brokenness of the currently documented example
    # it lacks the "minion_id" argument for "match.filter_by" and thereby
    # assigns the wrong roles
    with salt_master.pillar_tree.base.temp_file("top.sls", top_sls):
        with salt_master.pillar_tree.base.temp_file(
            "test_jinja.sls", sls_files[jinja_file]
        ):
            # Calling refresh_pillar to update in-memory pillars
            salt_cli.run(
                "saltutil.refresh_pillar", wait=True, minion_tgt=salt_minion.id
            )

            # Get the Minion's Pillar
            ret = salt_cli.run("pillar.get", "roles", minion_tgt=salt_minion.id)
            if app:
                assert "app" in ret.json
            else:
                assert "app" not in ret.json

            if caching:
                assert "caching" in ret.json
            else:
                assert "caching" not in ret.json

            if db:
                assert "db" in ret.json
            else:
                assert "db" not in ret.json

    # Refresh pillar once we're done
    salt_cli.run("saltutil.refresh_pillar", wait=True, minion_tgt=salt_minion.id)

def get_indexes(cursor, table_name):
    """
    Returns a dictionary of fieldname -> infodict for the given table,
    where each infodict is in the format:
        {'primary_key': boolean representing whether it's the primary key,
         'unique': boolean representing whether it's a unique index}
    """
    indexes = {}
    for info in _table_info(cursor, table_name):
        indexes[info['name']] = {'primary_key': info['pk'] != 0,
                                 'unique': False}
    cursor.execute('PRAGMA index_list(%s)' % quote_name(table_name))
    # seq, name, unique
    for index, unique in [(field[1], field[2]) for field in cursor.fetchall()]:
        if not unique:
            continue
        cursor.execute('PRAGMA index_info(%s)' % quote_name(index))
        info = cursor.fetchall()
        # Skip indexes across multiple fields
        if len(info) != 1:
            continue
        name = info[0][2] # seqno, cid, name
        indexes[name]['unique'] = True
    return indexes

